package com.linebook.customer.domain;

import jakarta.persistence.Column;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

@Entity
@Table(name = "customers")
public class Customer {

    @Id
    @Column(name = "id", length = 64, nullable = false, updatable = false)
    private String id;

    /** Creation order; generated by MySQL (AUTO_INCREMENT), read-only here. */
    @Column(name = "seq", insertable = false, updatable = false)
    private Long seq;

    @Column(name = "account_no", length = 32, nullable = false, updatable = false)
    private String accountNo;

    @Column(name = "name", length = 150, nullable = false)
    private String name;

    @Column(name = "phone", length = 15, nullable = false)
    private String phone;

    @Column(name = "address", length = 500, nullable = false)
    private String address;

    @Column(name = "area", length = 100, nullable = false)
    private String area;

    @Column(name = "stb_no", length = 32, nullable = false)
    private String stbNo;

    @Column(name = "vc_no", length = 32, nullable = false)
    private String vcNo;

    @Column(name = "package_id", length = 64, nullable = false)
    private String packageId;

    @Column(name = "monthly_rate", precision = 12, scale = 2, nullable = false)
    private BigDecimal monthlyRate;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", length = 16, nullable = false)
    private ConnectionStatus status;

    @Column(name = "recurring", nullable = false)
    private boolean recurring;

    @Column(name = "billing_day", nullable = false)
    private int billingDay;

    @Column(name = "agent_id", length = 64, nullable = false)
    private String agentId;

    @Column(name = "since_date", nullable = false, updatable = false)
    private LocalDate since;

    protected Customer() {
        // JPA
    }

    public Customer(String id, String accountNo, String name, String phone, String address, String area,
                    String stbNo, String vcNo, String packageId, BigDecimal monthlyRate,
                    ConnectionStatus status, boolean recurring, int billingDay, String agentId, LocalDate since) {
        this.id = id;
        this.accountNo = accountNo;
        this.name = name;
        this.phone = phone;
        this.address = address;
        this.area = area;
        this.stbNo = stbNo;
        this.vcNo = vcNo;
        this.packageId = packageId;
        this.monthlyRate = monthlyRate;
        this.status = status;
        this.recurring = recurring;
        this.billingDay = billingDay;
        this.agentId = agentId;
        this.since = since;
    }

    public void changeStatus(ConnectionStatus status, boolean recurring) {
        this.status = status;
        this.recurring = recurring;
    }

    public void changeRecurring(boolean recurring) {
        this.recurring = recurring;
    }

    public String getId() { return id; }
    public Long getSeq() { return seq; }
    public String getAccountNo() { return accountNo; }
    public String getName() { return name; }
    public String getPhone() { return phone; }
    public String getAddress() { return address; }
    public String getArea() { return area; }
    public String getStbNo() { return stbNo; }
    public String getVcNo() { return vcNo; }
    public String getPackageId() { return packageId; }
    public BigDecimal getMonthlyRate() { return monthlyRate; }
    public ConnectionStatus getStatus() { return status; }
    public boolean isRecurring() { return recurring; }
    public int getBillingDay() { return billingDay; }
    public String getAgentId() { return agentId; }
    public LocalDate getSince() { return since; }
}
